const raw=$input.first().json;
const b=raw.body??raw;
const from=String(b.from??b.phone??b.sender??'').replace(/[^0-9]/g,'');
const message=String(b.message??b.text??'').trim();
const requestId=String(b.request_id??b.event_id??'demo-'+Date.now());
const valid=from.length>=8 && from.length<=15 && message.length>0 && message.length<=1000;
return [{json:{valid,from,session_id:'wa_'+from,message,request_id:requestId,source:'webhook',received_at:new Date().toISOString(),error:valid?'': 'El remitente debe tener entre 8 y 15 dígitos y el mensaje entre 1 y 1000 caracteres.'}}];

const rows = $input.all()
  .map(item => item.json)
  .filter(row => row && !row.error && Object.keys(row).length > 0);

const operations = rows.slice(0, 40).map(row => ({
  tema: String(row.servicio ?? row.categoria ?? ""),
  estado: String(row.estado ?? ""),
  detalle: String(row.mensaje_cliente ?? ""),
  tiempo_estimado: String(row.tiempo_estimado ?? ""),
  categoria: String(row.categoria ?? "")
}));

const sourceError = $input.all().some(
  item => Boolean(item.json.error)
);

return [{
  json: {
    operational: operations,
    operations_available: operations.length > 0,
    sheets_error: sourceError,
    faq_rows: operations.length
  }
}];

const base=$('Normalizar y validar').first().json;
const raw=$input.first().json.output??$input.first().json.text??'';
let data;
try { const s=String(raw).replace(/^```(?:json)?\s*/i,'').replace(/```\s*$/,'').trim();data=JSON.parse(s); }catch(e){data=null;}
const choices=['answer','clarify','escalate'];
const valid=data && choices.includes(data.decision) && typeof data.answer==='string' && data.answer.trim().length>0 && data.answer.length<1500;
const decision=valid?data.decision:'escalate';
const answer=valid?data.answer.trim():'No puedo confirmar esa informacion en este momento. Te recomiendo contactar al equipo de soporte.';
return [{json:{ok:true,request_id:base.request_id,session_id:base.session_id,decision,answer,reason:valid?String(data.reason??'').slice(0,150):'agent_output_invalid_or_unavailable',source:valid?String(data.source??'none'):'none',requires_human:decision==='escalate',evaluated_at:new Date().toISOString()}}];
